              <legend className="art:mb-2 art:w-full art:px-3 art:pt-2 art:text-xl art:font-medium">{question.title}</legend>
              <div data-shortcuts="numbers" className="art:space-y-1">
                {question.kind === "radio" ? (question.options.map((option, i) => {
                    const checked = answers[question.name] === option.value;
                    const state = checked ? { "data-checked": "" } : { "data-unchecked": "" };
