                        <span id={labelId} className="art:relative art:z-10 art:min-w-0 art:flex-1 art:leading-5">
                          <span className="art:font-medium">{option.label}</span>{" "}
                          <span className="art:text-muted-foreground">{option.hint}</span>
                        </span>
                        <span aria-hidden="true" className="art:relative art:z-10 art:grid art:size-6 art:shrink-0 art:place-items-center art:rounded-lg art:border art:border-border art:text-xs art:tabular-nums art:text-muted-foreground">
